import { constructNowTimeValue } from './construct-now.js';
import { isSameSecondValue } from './is-same-second.js';
import { type TimeLike } from './types.js';

/**
 * @summary Is the given date in the same second as the current date?
 *
 * @description
 * Is the given date in the same second as the current date?
 *
 * @param date - The date to check
 *
 * @returns The date is in this second
 *
 * @example
 * // If now is 25 September 2014 18:30:15.500,
 * // is 25 September 2014 18:30:15.000 in this second?
 * const result = isThisSecond(new Date(2014, 8, 25, 18, 30, 15))
 * //=> true
 */
export function isThisSecond(date: Date | TimeLike): boolean {
  return isSameSecondValue(date, constructNowTimeValue(date));
}
